public readonly record struct Point(int X, int Y);

public class Route
{
    public Point Start { get; set; }                // part of every Route object's memory
    public Point[] Stops { get; } = new Point[16];  // 16 Points stored inline in one heap array

    public int Demo()
    {
        var a = new Point(1, 2);       // ordinary local: stack frame or CPU registers
        object boxed = a;              // boxing: copies a into a new object, normally on the heap
        var b = new Point(3, 4);       // captured by the lambda below: b lives in a closure object
        Func<int> shiftX = () => b.X + 1;
        return a.X + shiftX() + Start.X + Stops.Length + boxed.GetHashCode();
    }

    public async Task<int> LaterAsync(Task signal)
    {
        var c = new Point(5, 6);       // still needed after the await, so it becomes a field
        await signal;                  // of the async state machine, which is copied to the
        return c.X;                    // heap if the method really has to wait
    }
}

