public record struct OrderLine(string Sku, decimal Price);

var lines = new List<OrderLine> { new("SKU-1", 100m), new("SKU-2", 40m) };

for (var i = 0; i < lines.Count; i++)
{
    var line = lines[i];
    lines[i] = line with { Price = line.Price - 10m }; // store the new value back
}

Console.WriteLine(lines[0].Price); // 90

public readonly record struct OrderLine(string Sku, decimal Price);
